-- 碎片化
function randomstr(len)
    local res = ""
    for i = 1, len do
        local choice = math.random(1, 3)
        if choice == 1 then
            res = res .. string.char(math.random(65, 90))
        elseif choice == 2 then
            if i ~= 1 then
                res = res .. string.char(math.random(48, 57))
            else
                res = res .. string.char(math.random(97, 122))
            end
        elseif choice == 3 then
            res = res .. string.char(math.random(97, 122))
        end
    end
    return res
end

function topart(filein)
    local sprits_1, sprits_2 = "", ""
    local files1 = io.open(filein)
    repeat
        text = files1:read('*l')
        if text then
            if text ~= "" and load(text) and not text:find("return") then
                local tempt = randomstr(math.random(50, 60))
                sprits_1 = sprits_1 .. "\n" .. tempt .. "()\n"
                if math.random(1, 2) == 1 then
                    sprits_2 = sprits_2 .. "local function " .. tempt .. "()\n" .. text .. "\nend\n"
                else
                    sprits_2 = "local function " .. tempt .. "()\n" .. text .. "\nend\n" .. sprits_2
                end
            else
                sprits_1 = sprits_1 .. text .. "\n"
            end
        end
    until text == nil
    return sprits_2 .. sprits_1
end

-- 定义一个新方法
function Delt(t)
    -- 创建一个新的表
    local tab = {}
    -- index默认值为一  
    local index = 1
    -- 假如t不等于零则无限循环    
    while #t ~= 0 do
        -- n=从0~#t随机挑选一个数    
        local n = math.random(0, #t)
        -- 假如t[n]不等于空，则跳转     
        if t[n] ~= nil then
            -- 字面意思          
            tab[index] = t[n]
            -- 打印t这个表中的第n个值          
            table.remove(t, n)
            -- 如果不等于#t不等于零则无限循环 1+1       
            index = index + 1
        end
    end
    -- 最后返回这个表    
    return tab
end

--
function Jcip(j)
    local result = ''
    if j == result then
        return 'sQ()'
    end
    pd = nil
    for i = 1, #j do
        h = string.byte(j, i)
        if pd == nil then
            pd = 1
            result = result .. h
        else
            result = result .. ',' .. h
        end
    end
    local NR = 'sQ(' .. result .. ')'
    return NR
end

