    b = code
    -- 重新创建一个表并进行ascll码转换    
    tab = {b:byte(1, -1)}
    -- 返回上面那个表的大小排序    
    table.sort(tab, function(a, b)
        return a > b
    end)

    -- 定义一张新的表   
    K = {}
    -- 循环    
    for i = 1, #tab do
        -- 假如i等于1则跳转    
        if i == 1 then
            -- 在k这个表的尾部插入代码  
            table.insert(K, 'sQ(' .. tostring(tab[i]) .. ')')
            -- 假如不等于1    
        else
            -- 则计算另外一种情况    
            if 'sQ(' .. tostring(tab[i]) .. ')' == K[#K] then
            else
                -- 然后再次插入    
                table.insert(K, 'sQ(' .. tostring(tab[i]) .. ')')
            end
        end
    end

    -- K就等于最上面调用的东西
    K = Delt(K)
    -- 字面意思    
    q = ""
    -- 重新创建一个表并进行Ascll操作
    tab = {b:byte(1, -1)}
    -- 计算这个表的总长度进行循环    
    for i = 1, #tab do
        -- 然后遍历K的东西    
        for k, v in pairs(K) do
            ---假如sQ( .. tostring(tab[i]) .. )等于v则跳转
            if "sQ(" .. tostring(tab[i]) .. ")" == v then
                -- 字面意思      
                I = ",__k[" .. k .. "]"
            end
        end
        -- 字面意思
        q = q .. I
    end
    -- 进行替换操作
    q = q:gsub(",", "", 1)
    -- 字面意思    
    t = ""
    -- 计算#K的总长度进行循环 
    for i = 1, #K do
        -- 字面意思    
        t = t .. "," .. K[i]
    end
    -- 将上面的东西进行替换
    t = "{" .. t:gsub(",", "", 1) .. "}"
    -- 将所有东西进行整合    
    t = "load(string.dump(function() do  end " .. hunxiao .. " __k=" .. t .. "   P={" .. q .. "} " .. hunxiao ..
            "  return Lsq_(P,sQ()) end))()"
    -- 最后返回它    
    return t
end

